// Detect message type and extract relevant fields
const msg = $json.message || $json;

const userId    = String(msg.from?.id || '');
const username  = msg.from?.username || msg.from?.first_name || 'User';
const chatId    = String(msg.chat?.id || userId);
const text      = msg.text || msg.caption || '';
const messageId = String(msg.message_id || '');

// Detect type
let messageType = 'text';
if (msg.voice)    messageType = 'voice';
if (msg.audio)    messageType = 'voice';
if (msg.photo)    messageType = 'photo';
if (msg.document) messageType = 'document';

// Check for admin /ingest command
const adminUserId    = 'YOUR_TELEGRAM_ADMIN_USER_ID';
const isAdminIngest  = text.startsWith('/ingest') && userId === adminUserId;
if (isAdminIngest) messageType = 'admin_ingest';

// Extract media IDs
const voiceFileId    = msg.voice?.file_id    || msg.audio?.file_id    || '';
const photoFileId    = (msg.photo && msg.photo.length > 0) ? msg.photo[msg.photo.length - 1].file_id : '';
const documentFileId = msg.document?.file_id || '';
const documentMime   = msg.document?.mime_type || '';

// Session ID per user (used in the conversation log)
const sessionId = 'tg_' + userId;

// Extract doc URL from ingest command if applicable
const ingestUrl = isAdminIngest ? text.replace('/ingest', '').trim() : '';

return [{
  json: {
    userId, username, chatId, text, messageId,
    messageType, voiceFileId, photoFileId,
    documentFileId, documentMime, sessionId,
    ingestUrl, isAdminIngest
  }
}];

// Build the final query text from whatever input type came in
// All branches converge here
const detect = $('2. Code - Detect Message Type').first().json;

let queryText  = '';
let inputType  = detect.messageType;

// Text branch
if (inputType === 'text') {
  queryText = detect.text || '';
}

// Voice branch - Whisper output
if (inputType === 'voice') {
  try {
    const transcribeOut = $('6. OpenAI - Transcribe Voice to Text').first().json;
    queryText = transcribeOut.text || transcribeOut.transcript || '';
    if (!queryText) queryText = detect.text || '';
  } catch(e) {
    queryText = detect.text || '';
  }
}

// Photo branch - Vision description
if (inputType === 'photo') {
  try {
    const visionOut = $('9. OpenAI - Analyze Image with Vision').first().json;
    const description = visionOut.content || visionOut.text || '';
    const caption = detect.text || '';
    queryText = (caption ? 'Image caption: ' + caption + '\n' : '') + 'Image description: ' + description;
  } catch(e) {
    queryText = detect.text || 'User sent an image';
  }
}

// Document branch - PDF text
if (inputType === 'document') {
  try {
    const pdfOut = $('12. Extract From File - Read PDF Text').first().json;
    const pdfText  = (pdfOut.text || '').substring(0, 8000);
    const caption  = detect.text || '';
    queryText = (caption ? 'Document caption: ' + caption + '\n' : '') + 'Document content: ' + pdfText;
  } catch(e) {
    queryText = detect.text || 'User sent a document';
  }
}

// Admin ingest - no query needed, handled separately
if (inputType === 'admin_ingest') {
  queryText = '__ADMIN_INGEST__';
}

if (!queryText && !detect.text) {
  queryText = 'User sent a message I could not read. Please ask them to send text.';
}

return [{
  json: {
    queryText,
    inputType,
    userId:    detect.userId,
    username:  detect.username,
    chatId:    detect.chatId,
    sessionId: detect.sessionId,
    ingestUrl: detect.ingestUrl,
    isAdminIngest: detect.isAdminIngest
  }
}];

// Build RAG context from Pinecone search results
// Merge query context with retrieved chunks
const pineconeResp = $json;
const queryCtx     = $('13. Code - Build Query Text from Any Input').first().json;
const embedResp    = $('14. HTTP - OpenAI Embed Query').first().json;

const matches = pineconeResp.matches || [];

// Build context string from top 3 matches
const chunkTexts = matches.map(function(m, i) {
  const text   = m.metadata?.text || m.metadata?.content || '';
  const source = m.metadata?.source || m.metadata?.doc_id || 'Knowledge Base';
  const score  = m.score ? m.score.toFixed(3) : '?';
  return 'Chunk ' + (i + 1) + ' (relevance: ' + score + ', source: ' + source + '):\n' + text;
}).join('\n\n---\n\n');

const ragContext = chunkTexts || 'No relevant knowledge base content found for this query.';
const chunksUsed = matches.length;

// Check if admin ingest command
if (queryCtx.isAdminIngest) {
  return [{
    json: {
      queryText:   queryCtx.queryText,
      ragContext,
      chunksUsed,
      userId:    queryCtx.userId,
      username:  queryCtx.username,
      chatId:    queryCtx.chatId,
      sessionId: queryCtx.sessionId,
      ingestUrl: queryCtx.ingestUrl,
      isAdminIngest: true,
      inputType: queryCtx.inputType
    }
  }];
}

return [{
  json: {
    queryText:   queryCtx.queryText,
    ragContext,
    chunksUsed,
    userId:    queryCtx.userId,
    username:  queryCtx.username,
    chatId:    queryCtx.chatId,
    sessionId: queryCtx.sessionId,
    ingestUrl: queryCtx.ingestUrl,
    isAdminIngest: false,
    inputType: queryCtx.inputType
  }
}];

