// Format bot reply and collect all data for logging
const aiResp   = $json;
const ragCtx   = $('16. Code - Build RAG Context from Results').first().json;

const rawReply = aiResp?.choices?.[0]?.message?.content || 'Sorry, I could not generate a response. Please try again.';

// For admin ingest - give status message
if (ragCtx.isAdminIngest) {
  return [{
    json: {
      replyText:   'Admin: Ingestion command received for URL: ' + ragCtx.ingestUrl + '. The ingestion pipeline runs as a separate workflow. Please run your ingestion workflow to chunk, embed, and upload this document to Pinecone.',
      queryText:   ragCtx.queryText,
      ragContext:  ragCtx.ragContext,
      chunksUsed:  ragCtx.chunksUsed,
      userId:      ragCtx.userId,
      username:    ragCtx.username,
      chatId:      ragCtx.chatId,
      sessionId:   ragCtx.sessionId,
      inputType:   ragCtx.inputType,
      loggedAt:    new Date().toISOString()
    }
  }];
}

// Telegram message limit is 4096 chars. Truncate if needed.
const replyText = rawReply.length > 4000
  ? rawReply.substring(0, 3997) + '...'
  : rawReply;

return [{
  json: {
    replyText,
    queryText:   ragCtx.queryText,
    ragContext:  ragCtx.ragContext,
    chunksUsed:  ragCtx.chunksUsed,
    userId:      ragCtx.userId,
    username:    ragCtx.username,
    chatId:      ragCtx.chatId,
    sessionId:   ragCtx.sessionId,
    inputType:   ragCtx.inputType,
    loggedAt:    new Date().toISOString()
  }
}];
